import { readFileSync } from 'node:fs';
import { createServer } from 'node:http';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);

const evmAccounts = JSON.parse(
  readFileSync(
    require.resolve('inference-work-lot-service/content/evm/accounts/eip155-31337.json'),
    'utf-8'
  )
);

const PORT = Number(process.env.PORT ?? '8080');
const HOST = process.env.HOST ?? '127.0.0.1';
const BASE_URL = process.env.BASE_URL ?? `http://${HOST}:${PORT}`;

function jsonActivity(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/activity+json' });
  res.end(JSON.stringify(body));
}

createServer((req, res) => {
  if (req.method !== 'GET') {
    jsonActivity(res, 405, { error: 'method not allowed' });
    return;
  }
  if (req.url === '/') {
    jsonActivity(res, 200, {
      '@context': 'https://www.w3.org/ns/activitystreams',
      id: BASE_URL,
      type: 'Service',
      name: 'free-compute-dev',
      summary: 'ActivityPub face for the free-compute-dev inference work lot service',
      preferredUsername: 'free-compute-dev',
    });
    return;
  }
  jsonActivity(res, 404, { error: 'not found' });
}).listen(PORT, HOST, () => {
  console.log(`activitypub face listening at ${BASE_URL} with ${evmAccounts.accounts?.length ?? 0} eip155-31337 accounts`);
});
